SELECT YEAR(a.opened_date) AS opened_year, a.account_type, SUM(CASE WHEN t.txn_type = 'FEE' THEN t.amount ELSE 0 END) AS fee_amount FROM transactions t LEFT OUTER JOIN accounts a ON t.account_id = a.id LEFT OUTER JOIN customers c ON a.customer_id = c.id GROUP BY YEAR(a.opened_date), a.account_type HAVING SUM(CASE WHEN t.txn_type = 'FEE' THEN t.amount ELSE 0 END) > 30 ORDER BY fee_amount DESC
